import numpy as np
from PIL import Image
im=np.array(Image.open('/app/output/blue_liftcheck_ego.png'))
R,G,B=[im[:,:,i] for i in range(3)]
masks={'red':(R>120)&(R>G*1.6)&(R>B*1.6),'green':(G>90)&(G>R*1.35)&(G>B*1.2),'blue':(B>80)&(B>R*1.4)&(B>G*1.15)}
for name,m in masks.items():
 y,x=np.nonzero(m)
 if len(x): print(name,len(x),'bbox',(x.min(),y.min(),x.max(),y.max()),'centroid',np.mean(x),np.mean(y))
PY

